def llenar_codigos_de_fotos(apps, schema_editor):
    """Asigna un uuid4 distinto a cada foto existente.

    RunPython justificado: un AddField con default callable evalúa uuid4() una
    sola vez y repetiría el mismo valor en todas las filas, lo que rompe la
    restricción de unicidad; hay que generar un valor por fila.
    """
    Foto = apps.get_model("visitas", "Foto")
    for foto in Foto.objects.filter(codigo__isnull=True).iterator():
        foto.codigo = uuid.uuid4()
        foto.save(update_fields=["codigo"])


